class api extends Core { const VERSION = '1.0'; const REALNAME = 'API de lecture (IA)'; const DELETE = true; const DATADIRECTORY = ''; const MULTIMODULE = false; public static $actions = [ 'index' => self::ROLE_VISITOR, 'pages' => self::ROLE_VISITOR, 'content' => self::ROLE_VISITOR, 'search' => self::ROLE_VISITOR, ]; const ARTICLE_MODULES = ['blog', 'news']; const EXCERPT_LENGTH = 400; public function index() { if (!$this->isLlmsAllowed()) { $this->deny(); return; } $lang = $this->resolveLanguage(); $state = $this->withLanguage($lang, function () { $siteRoot = $this->siteRootUrl(); return [ 'api' => [ 'name' => 'API de lecture pour modèles de langage', 'version' => self::VERSION, 'readOnly' => true, 'format' => 'application/json', 'language' => self::$siteContent, ], 'site' => [ 'title' => $this->decodeHtml((string) $this->getData(['locale', 'title'])), 'description' => $this->decodeHtml(trim((string) $this->getData(['locale', 'metaDescription']))), 'baseUrl' => $siteRoot, 'languages' => $this->installedLanguages(), ], 'endpoints' => [ [ 'method' => 'GET', 'path' => '/api/pages', 'description' => 'Arborescence des pages publiques et de leurs articles publiés.', ], [ 'method' => 'GET', 'path' => '/api/content/<pageId>[/<articleId>]', 'description' => 'Contenu complet d\'une page ou d\'un article.', ], [ 'method' => 'GET', 'path' => '/api/search/<termes>[/<limit>]', 'description' => 'Recherche plein texte dans les pages et articles.', ], ], 'llmsTxt' => $siteRoot . 'llms.txt', ]; }); $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => $state, ]); } public function pages() { if (!$this->isLlmsAllowed()) { $this->deny(); return; } $lang = $this->resolveLanguage(); $result = $this->withLanguage($lang, function () { return [ 'language' => self::$siteContent, 'baseUrl' => $this->siteRootUrl(), 'pages' => $this->collectPages(), ]; }); $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => $result, ]); } public function content() { if (!$this->isLlmsAllowed()) { $this->deny(); return; } $path = $this->getRequestString('path'); if ($path === '') { $segments = []; for ($i = 2; $i <= 3; $i++) { $segment = $this->getUrl($i); if ($segment !== null && $segment !== '') { $segments[] = $segment; } } $path = implode('/', $segments); } $path = trim(rawurldecode((string) $path), '/'); if ($path === '') { $this->error(400, 'Paramètre "path" requis (format : <pageId>[/<articleId>]).'); return; } $segments = explode('/', $path); $pageId = $segments[0]; $articleId = $segments[1] ?? null; $lang = $this->resolveLanguage(); $result = $this->withLanguage($lang, function () use ($pageId, $articleId) { if ($this->getData(['page', $pageId]) === null || !$this->isPagePublic($pageId)) { return null; } $baseUrl = $this->publicBaseUrl(); $langParam = $this->languageQuerySuffix(self::$siteContent); if ($articleId === null) { $content = [ 'type' => 'page', 'language' => self::$siteContent, 'id' => $pageId, 'title' => $this->decodeHtml((string) $this->getData(['page', $pageId, 'title'])), 'url' => $baseUrl . $pageId . $langParam, 'metaDescription' => $this->decodeHtml((string) $this->getData(['page', $pageId, 'metaDescription'])), 'content' => $this->pageContentForApi($pageId), 'articles' => $this->collectPageArticles($pageId), ]; return $content; } $article = $this->findArticle($pageId, $articleId); if ($article === null) { return null; } return [ 'type' => 'article', 'language' => self::$siteContent, 'id' => $articleId, 'pageId' => $pageId, 'title' => $this->decodeHtml((string) ($article['title'] ?? '')), 'url' => $baseUrl . $pageId . '/' . $articleId . $langParam, 'publishedOn' => (int) ($article['publishedOn'] ?? 0), 'publishedOnIso' => $this->isoDate((int) ($article['publishedOn'] ?? 0)), 'content' => $this->cleanHtml(Helper::cleanRssText((string) ($article['content'] ?? ''))), 'excerpt' => $this->excerpt((string) ($article['content'] ?? '')), ]; }); if ($result === null) { $this->error(404, 'Page ou article introuvable ou non public.'); return; } $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => $result, ]); } public function search() { if (!$this->isLlmsAllowed()) { $this->deny(); return; } $query = trim((string) $this->getRequestString('q')); if ($query === '') { $query = trim((string) $this->getUrl(2)); } $query = trim(rawurldecode($query)); if ($query === '') { $this->error(400, 'Paramètre "q" requis (termes de recherche).'); return; } $limit = (int) $this->getRequestString('limit'); if ($limit <= 0) { $limit = (int) $this->getUrl(3); } $limit = $limit > 0 ? min($limit, 100) : 20; $terms = []; foreach (preg_split('/\s+/', $query) as $term) { if (mb_strlen($term, 'UTF-8') >= 2) { $terms[] = $term; } } if ($terms === []) { $this->error(400, 'Aucun terme de recherche valide (2 caractères minimum).'); return; } $lang = $this->resolveLanguage(); $result = $this->withLanguage($lang, function () use ($terms, $limit) { $baseUrl = $this->publicBaseUrl(); $langParam = $this->languageQuerySuffix(self::$siteContent); $matches = []; foreach ($this->walkPublicPages() as $pageId) { $pageTitle = $this->decodeHtml((string) $this->getData(['page', $pageId, 'title'])); $pageText = $this->decodeHtml(strip_tags((string) $this->pageContentForApi($pageId))); $score = $this->countMatches($pageTitle . ' ' . $pageText, $terms); if ($score > 0) { $matches[] = [ 'type' => 'page', 'id' => $pageId, 'title' => $pageTitle, 'url' => $baseUrl . $pageId . $langParam, 'excerpt' => $this->snippet($pageText, $terms), 'score' => $score, ]; } foreach ($this->collectPageArticles($pageId) as $article) { $articleData = $this->findArticle($pageId, $article['id']); $articleText = $this->decodeHtml(strip_tags((string) ($articleData['content'] ?? ''))); $articleScore = $this->countMatches($article['title'] . ' ' . $articleText, $terms); if ($articleScore > 0) { $matches[] = [ 'type' => 'article', 'id' => $article['id'], 'pageId' => $pageId, 'title' => $article['title'], 'url' => $article['url'], 'publishedOn' => $article['publishedOn'], 'excerpt' => $this->snippet($articleText, $terms), 'score' => $articleScore, ]; } } } usort($matches, function ($a, $b) { if ($a['score'] === $b['score']) { $dateA = $a['publishedOn'] ?? 0; $dateB = $b['publishedOn'] ?? 0; return $dateB <=> $dateA; } return $b['score'] <=> $a['score']; }); return [ 'language' => self::$siteContent, 'query' => implode(' ', $terms), 'count' => count($matches), 'results' => array_slice($matches, 0, $limit), ]; }); $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => $result, ]); } private function isLlmsAllowed() { return $this->getData(['config', 'seo', 'llms']) === true; } private function deny() { $this->error(403, 'L\'accès du site aux modèles de langage (IA) est désactivé.'); } private function error($code, $message) { http_response_code($code); $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => [ 'error' => [ 'code' => $code, 'message' => $message, ], ], ]); } private function resolveLanguage() { foreach (['lang', 'l'] as $param) { $requested = $this->getRequestString($param); if ( $requested !== '' && array_key_exists($requested, self::$languages) && is_dir(self::DATA_DIR . $requested) ) { return $requested; } } return self::$siteContent; } private function withLanguage($lang, callable $callback) { $savedSiteContent = self::$siteContent; try { if ($lang !== $savedSiteContent) { self::$siteContent = $lang; $this->jsonDB($lang, ['page', 'module', 'locale']); $this->buildHierarchy(); } return $callback(); } finally { self::$siteContent = $savedSiteContent; $this->jsonDB($savedSiteContent, ['page', 'module', 'locale']); $this->buildHierarchy(); } } private function installedLanguages() { $languages = []; foreach (self::$languages as $langId => $label) { if (is_dir(self::DATA_DIR . $langId)) { $languages[$langId] = $label; } } return $languages; } private function walkPublicPages() { $ordered = []; $visited = []; $walk = function ($pageId, $depth) use (&$walk, &$ordered, &$visited) { if (isset($visited[$pageId]) || !$this->isPagePublic($pageId) || $depth > self::MENU_DEPTH) { return; } $visited[$pageId] = true; $ordered[] = $pageId; foreach ($this->getHierarchy($pageId) as $childId) { $walk($childId, $depth + 1); } }; foreach ($this->getHierarchy() as $parentId => $children) { $walk($parentId, 0); } return $ordered; } private function collectPages() { $visited = []; $build = function ($pageId, $depth) use (&$build, &$visited) { if (isset($visited[$pageId]) || !$this->isPagePublic($pageId) || $depth > self::MENU_DEPTH) { return null; } $visited[$pageId] = true; $node = [ 'id' => $pageId, 'title' => $this->decodeHtml((string) $this->getData(['page', $pageId, 'title'])), 'url' => $this->publicBaseUrl() . $pageId . $this->languageQuerySuffix(self::$siteContent), 'articles' => $this->collectPageArticles($pageId), 'children' => [], ]; foreach ($this->getHierarchy($pageId) as $childId) { $childNode = $build($childId, $depth + 1); if ($childNode !== null) { $node['children'][] = $childNode; } } return $node; }; $tree = []; foreach ($this->getHierarchy() as $parentId => $children) { $node = $build($parentId, 0); if ($node !== null) { $tree[] = $node; } } return $tree; } private function isPagePublic($pageId) { return $this->getData(['page', $pageId]) !== null && $this->getData(['page', $pageId, 'role']) === self::ROLE_VISITOR && $this->getData(['page', $pageId, 'block']) !== 'bar' && $this->getData(['page', $pageId, 'disable']) !== true; } private function pageContentForApi($pageId) { $html = (string) $this->getPage($pageId, self::$siteContent); return $this->cleanHtml(Helper::cleanRssText($html)); } private function collectPageArticles($pageId) { $articles = []; $now = time(); $baseUrl = $this->publicBaseUrl(); $langParam = $this->languageQuerySuffix(self::$siteContent); foreach ($this->getArticleInstances($pageId) as $instanceId) { foreach ((array) $this->getData(['module', $instanceId, 'posts']) as $articleId => $article) { $publishedOn = (int) ($article['publishedOn'] ?? 0); if (($article['state'] ?? false) !== true || $publishedOn > $now) { continue; } $articles[] = [ 'id' => $articleId, 'title' => $this->decodeHtml((string) ($article['title'] ?? '')), 'url' => $baseUrl . $pageId . '/' . $articleId . $langParam, 'publishedOn' => $publishedOn, 'publishedOnIso' => $this->isoDate($publishedOn), 'excerpt' => $this->excerpt((string) ($article['content'] ?? '')), ]; } } usort($articles, function ($a, $b) { return $b['publishedOn'] <=> $a['publishedOn']; }); return $articles; } private function getArticleInstances($pageId) { $page = (array) $this->getData(['page', $pageId]); $instances = []; $pageModules = $page['pageModules'] ?? null; if (is_array($pageModules) && $pageModules !== []) { foreach ($pageModules as $instanceId => $config) { if (in_array($config['moduleId'] ?? '', self::ARTICLE_MODULES, true)) { $instances[] = $instanceId; } } } elseif (!empty($page['moduleId']) && in_array($page['moduleId'], self::ARTICLE_MODULES, true)) { $zone = $page['modulePosition'] ?? 'bottom'; $pageKey = Helper::filter((string) $pageId, Helper::FILTER_ID); $instances[] = $page['moduleId'] . ($pageKey !== '' ? '-' . $pageKey : '') . '-' . $zone; } return $instances; } private function findArticle($pageId, $articleId) { $now = time(); foreach ($this->getArticleInstances($pageId) as $instanceId) { $article = $this->getData(['module', $instanceId, 'posts', $articleId]); if ( is_array($article) && ($article['state'] ?? false) === true && (int) ($article['publishedOn'] ?? 0) <= $now ) { return $article; } } return null; } private function publicBaseUrl() { return Helper::baseUrl(); } private function siteRootUrl() { return rtrim(Helper::baseUrl(false), '/') . '/'; } private function languageQuerySuffix($lang) { if (file_exists(self::DATA_DIR . $lang . '/.default')) { return ''; } $separator = Helper::checkRewrite() ? '?' : '&'; return $separator . 'l=' . rawurlencode($lang); } private function getRequestString($name) { $value = $_GET[$name] ?? $_POST[$name] ?? ''; if (is_array($value)) { return ''; } return trim((string) $value); } private function decodeHtml($text) { return html_entity_decode((string) $text, ENT_QUOTES | ENT_HTML5, 'UTF-8'); } private function cleanHtml($html) { return trim((string) $html); } private function excerpt($html, $maxLength = self::EXCERPT_LENGTH) { $text = $this->decodeHtml(strip_tags(Helper::cleanRssText((string) $html))); $text = trim(preg_replace('/\s+/', ' ', $text)); if ($maxLength > 0 && mb_strlen($text, 'UTF-8') > $maxLength) { $text = mb_substr($text, 0, $maxLength, 'UTF-8'); $lastSpace = mb_strrpos($text, ' ', 0, 'UTF-8'); if ($lastSpace !== false && $lastSpace > 0) { $text = mb_substr($text, 0, $lastSpace, 'UTF-8'); } $text .= '…'; } return $text; } private function snippet($text, $terms, $length = 240) { $text = trim(preg_replace('/\s+/', ' ', (string) $text)); if ($text === '') { return ''; } $position = -1; foreach ($terms as $term) { $found = mb_stripos($text, $term, 0, 'UTF-8'); if ($found !== false && ($position === -1 || $found < $position)) { $position = $found; } } if ($position === -1) { $position = 0; } $start = max(0, $position - 60); $snippet = mb_substr($text, $start, $length, 'UTF-8'); if ($start > 0) { $snippet = '…' . $snippet; } if ($start + $length < mb_strlen($text, 'UTF-8')) { $snippet .= '…'; } return $snippet; } private function countMatches($text, $terms) { $score = 0; foreach ($terms as $term) { $count = @preg_match_all('/' . preg_quote($term, '/') . '/iu', $text); if (is_int($count)) { $score += $count; } } return $score; } private function isoDate($timestamp) { if ($timestamp <= 0) { return ''; } return gmdate('Y-m-d\TH:i:s\Z', $timestamp); } }
